import 'package:flutter/material.dart';import '../services/server_config.dart';import '../services/api_service.dart';
class ServerSettingsScreen extends StatefulWidget{const ServerSettingsScreen({super.key});@override State<ServerSettingsScreen> createState()=>_ServerSettingsScreenState();}
class _ServerSettingsScreenState extends State<ServerSettingsScreen>{final c=TextEditingController();String message='';bool busy=false;@override void initState(){super.initState();ServerConfig.getUrl().then((v){if(mounted)c.text=v;});}Future<void> save()async{await ServerConfig.save(c.text);setState(()=>message='URL guardada');}Future<void> test()async{setState((){busy=true;message='Probando conexión...';});try{await ServerConfig.save(c.text);await ApiService().test();setState(()=>message='Conexión correcta');}catch(e){setState(()=>message='Error: $e');}finally{setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Configuración del servidor')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[TextField(controller:c,decoration:const InputDecoration(labelText:'URL de la API',hintText:'http://10.0.2.2:3000',border:OutlineInputBorder())),const SizedBox(height:12),const Text('Emulador: http://10.0.2.2:3000\nCelular Wi-Fi: http://IP-DE-LA-LAPTOP:3000\nUSB con ADB reverse: http://127.0.0.1:3000'),const SizedBox(height:16),FilledButton(onPressed:save,child:const Text('Guardar URL')),OutlinedButton(onPressed:busy?null:test,child:Text(busy?'Probando...':'Probar conexión')),Text(message)])));}}